PROFILE Full

COMPONENT RigidBodyPhysics : 2

DEF RBC RigidBodyCollection {
  bodies [
    DEF A RigidBody {
      fixed TRUE
      position 0 5 0
      geometry DEF A_C CollidableShape {
        translation 0 5 0
        shape Shape {
          geometry Box {
            size 0.5 0.5 0.5
          }
        }
      }
    }
    DEF B RigidBody {
      position -2.22045e-16 3.999998 0
      linearVelocity 9.613752e-20 0.0004948163 0
      geometry DEF B_C CollidableShape {
        translation -2.22045e-16 3.999998 0
        shape Shape {
          geometry Box {
            size 1 1 1
          }
        }
      }
    }
  ]
  joints DEF J SliderJoint {
    minSeparation -1
    body1 USE A
    body2 USE B
  }
}

